  const priceSeriesNames: string[] = [];
  const series: any[] = [
    // One stepline per price provenance, colored like the Ceny tab badges.
    ...(["certain", "forecast", "estimated"] as PriceType[]).map((t) => {
      const name = `Cena ${PRICE_TYPE_META[t].label}`;
